{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Tropisetron, a tertiary N-methyl tropane ester, has absolute oral bioavailability of 66% in healthy volunteers, demonstrating that the tropane ester scaffold with a basic tertiary amine can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Cocaine, another tertiary tropane ester, shows human oral bioavailability of 32 ± 4%, supporting F ≥20% for the query's similar tropane tertiary amine ester.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Meperidine, a tertiary amine phenylpiperidine ester, has about 50% oral bioavailability despite first-pass metabolism, indicating that basic ester-containing drugs can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ipratropium, the highest-similarity analogue, has only ~2% oral bioavailability, but it is a quaternary ammonium salt; the query's tertiary amine lacks the permanent charge that dominates this poor absorption, so this low-F evidence transfers weakly.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tiotropium, another quaternary ammonium tropane, also has 2-3% oral bioavailability, again attributable to its permanent positive charge rather than the shared tropane ester motif.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Phenoperidine, a tertiary amine phenylpiperidine ester, has ~10-14% oral bioavailability, but its ethyl ester and N-hydroxy-phenylpropyl substituent differ from the tropane tropate scaffold, and its low F reflects extensive first-pass metabolism; this provides only weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a tertiary tropane alkaloid ester (scopolamine-like). High-F tertiary tropane/piperidine esters (tropisetron, cocaine, meperidine) are more transferable than low-F quaternary ammonium analogues (ipratropium, tiotropium), and the mixed physicochemical prior does not override this. F ≥20% is better supported.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for scopolamine itself is included in the evidence set.",
    "First-pass metabolism and ester hydrolysis of the tropate ester in the query are not directly assessed.",
    "Quaternary vs tertiary amine differences limit direct extrapolation from ipratropium and tiotropium."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

